function _kind<K extends UpdateKind>(k: K): Filter<UpdateKindMap[K]> {
    return defineFilter(`kind.${k}`, (u: unknown): u is UpdateKindMap[K] => (u as {
        kind?: string;
    }).kind === k, { kinds: [k] }) as Filter<UpdateKindMap[K]>;
}

